 values('d3401000-0000-4000-8000-000000000002','d3400000-0000-4000-8000-000000000001','Legado em andamento','frequency',date_trunc('week',now())::date-7,date_trunc('week',now())::date-1,now()-interval '8 days',5,'{"participation":2,"winner":5}');
create table arena_legacy_baseline(table_name text primary key,digest text);
do $$ declare name text;value text;begin foreach name in array array['gf_challenges','gf_challenge_members','coin_wallets','coin_movements','group_days','gf_badges','gf_accounts','medical_kits'] loop execute format('select md5(coalesce(string_agg(to_jsonb(x)::text,''|'' order by to_jsonb(x)::text),'''')) from public.%I x',name) into value;insert into arena_legacy_baseline values(name,value);end loop;end $$;
